import ast, base64, difflib, hashlib, json, os, pathlib, stat, tempfile, time, types
data=json.loads(base64.b64decode(''))
old,new=data['before'],data['after']
oldtree,newtree=ast.parse(old),ast.parse(new)
compile(new, '<fresh-launcher-source>', 'exec')
olddefs={n.name:n for n in oldtree.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
newdefs={n.name:n for n in newtree.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
checks=[]
def check(name,value):
    assert value,name
    checks.append({'name':name,'passed':True})
for name,node in olddefs.items():
    check('original_definition_unchanged:'+name,ast.dump(node,include_attributes=False)==ast.dump(newdefs[name],include_attributes=False))
check('exact_two_new_helpers',set(newdefs)-set(olddefs)=={'create_fresh_target','preserve_current_early_failure'})
check('same_original_outer_constant',"ORIGINAL_OUTER_SECONDS = 12000" in new)
check('original_source_and_cargo_home_literals',"SOURCE = ROOT / 'source'" in new and "CARGO_HOME = '/home/qian-qi/heptabao-native-20261029-c1bd-r1/cargo-home'" in new)
check('target_after_all_original_fences',new.index("result['retained_failed_observer'] = preserve_failed_observer()",new.index("lock_fd = None")) < new.index("create_fresh_target(result['fresh_target_preparation'])") < new.index("result['compiler_holders_before_lock'] = holders()"))
selected=ast.Module(body=[newdefs['identity'],newdefs['create_fresh_target']],type_ignores=[])
code=compile(ast.fix_missing_locations(selected),'<actual-selected-methods>','exec')
results=[]
class OsProxy:
    def __init__(self,close_error=False,replace_release=False):
        self.close_error=close_error
        self.replace_release=replace_release
        self.opened=[]
        self.close_calls=[]
        self.failed_fd=None
        self.root=None
        self.replaced=False
    def __getattr__(self,name): return getattr(os,name)
    def open(self,*a,**kw):
        fd=os.open(*a,**kw);self.opened.append(fd);return fd
    def close(self,fd):
        self.close_calls.append(fd)
        if self.close_error and self.failed_fd is None:
            self.failed_fd=fd
            raise OSError('synthetic_close_failure')
        return os.close(fd)
    def fsync(self,fd):
        os.fsync(fd)
        if self.replace_release and not self.replaced:
            self.replaced=True
            release=self.root/'target-normal-r3'/'release'
            release.rename(self.root/'target-normal-r3'/'held-old-release')
            release.mkdir(mode=0o700)
def run_case(name,expired=False,existing=False,close_error=False,replace_release=False):
    with tempfile.TemporaryDirectory(prefix='heptabao-fresh-cache-source-component-') as temp:
        root=pathlib.Path(temp)/'owned'
        root.mkdir(mode=0o700)
        target=root/'target-normal-r3'
        if existing:
            target.mkdir(mode=0o700)
            (target/'preserved').write_bytes(b'original')
        proxy=OsProxy(close_error,replace_release);proxy.root=root
        ns={'os':proxy,'stat':stat,'time':time,'ROOT':root,'TARGET':target,'expected_uid':os.getuid(),'OUTER_UNTIL':time.monotonic()+(-1 if expired else 3)}
        exec(code,ns)
        proof={}
        error=None
        try:
            ns['create_fresh_target'](proof)
        except BaseException as e:
            error=type(e).__name__
        finally:
            if proxy.failed_fd is not None:
                os.close(proxy.failed_fd)
        if name=='success':
            check(name,error is None and proof['status']=='prepared' and proof['all_opened_descriptors_closed'] and len(proxy.opened)==4 and len(proxy.close_calls)==4 and target.is_dir() and (target/'release/.cargo-lock').stat().st_size==0 and stat.S_IMODE((target/'release/.cargo-lock').stat().st_mode)==0o600)
        elif name=='existing_target_refused_without_overwrite':
            check(name,error=='FileExistsError' and (target/'preserved').read_bytes()==b'original' and not (target/'release').exists() and proof['created']==[] and proof['all_opened_descriptors_closed'])
        elif name=='expired_before_first_open':
            check(name,error=='AssertionError' and not target.exists() and not proxy.opened and proof['created']==[])
        elif name=='close_failure_continues_all_closes_and_refuses':
            check(name,error=='RuntimeError' and len(proxy.close_calls)==4 and len(set(proxy.close_calls))==4 and proof['status']=='descriptor_close_failed' and proof['all_opened_descriptors_closed'] is False and sum(not x['closed'] for x in proof['descriptors'])==1)
        elif name=='named_release_replacement_refused':
            check(name,error=='AssertionError' and proxy.replaced and proof['all_opened_descriptors_closed'] and len(proxy.close_calls)==4)
        results.append({'name':name,'error_type':error,'opened_fds':len(proxy.opened),'close_attempts':len(proxy.close_calls),'test_harness_extra_close':1 if proxy.failed_fd is not None else 0,'proof':proof})
run_case('success')
run_case('existing_target_refused_without_overwrite',existing=True)
run_case('expired_before_first_open',expired=True)
run_case('close_failure_continues_all_closes_and_refuses',close_error=True)
run_case('named_release_replacement_refused',replace_release=True)
print(json.dumps({'schema':'heptabao.fresh-target-selected-source-components.v1','before_sha256':hashlib.sha256(old.encode()).hexdigest(),'after_sha256':hashlib.sha256(new.encode()).hexdigest(),'original_helper_count':len(olddefs),'checks':checks,'count':len(checks),'selected_actual_methods_only':True,'actual_local_owned_temp_files':True,'remote_calls':0,'children':0,'cargo':0,'module_executed':False,'cases':results,'diff':''.join(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='before/launch_normal_cold_h2.py',tofile='after/launch_normal_cold_h2.py')),'reverse_diff':''.join(difflib.unified_diff(new.splitlines(True),old.splitlines(True),fromfile='after/launch_normal_cold_h2.py',tofile='before/launch_normal_cold_h2.py'))},sort_keys=True))
